# Release layout
/var/www/app/
  releases/20260911_1430/   # full checkout + vendor + built assets + caches
  shared/  .env  storage/   # persisted across releases
  current -> releases/20260911_1430

# deploy steps (Deployer / Envoyer / your Action) — nothing touches `current` until the end
R=/var/www/app/releases/$(date +%Y%m%d_%H%M%S)
git clone --depth 1 -b main git@github.com:corebari/app.git $R
cd $R && composer install --no-dev --optimize-autoloader --no-interaction
ln -sfn /var/www/app/shared/.env $R/.env && rm -rf $R/storage && ln -sfn /var/www/app/shared/storage $R/storage
php artisan config:cache && php artisan route:cache && php artisan view:cache && php artisan event:cache
php artisan migrate --force            # expand-only migrations, safe for the OLD code
php artisan about > /dev/null          # boots the app: catches config errors before switching
ln -sfn $R /var/www/app/current_tmp && mv -T /var/www/app/current_tmp /var/www/app/current   # atomic switch
sudo systemctl reload php8.3-fpm       # opcache/realpath refresh
php artisan horizon:terminate          # workers exit after current job; Supervisor restarts on new code
curl -fsS https://app.corebari.com/up  # health check; on failure: mv the symlink back
ls -dt /var/www/app/releases/* | tail -n +6 | xargs rm -rf   # keep 5 for rollback

# Expand → migrate → contract for renaming orders.total to total_minor
# Release N (expand): add the column, no NOT NULL yet
Schema::table('orders', fn (Blueprint $t) => $t->unsignedBigInteger('total_minor')->nullable()->after('total'));
# MySQL 8: ALTER TABLE orders ADD COLUMN total_minor BIGINT UNSIGNED NULL, ALGORITHM=INSTANT  (metadata only)
# New code: writes BOTH total and total_minor; reads total_minor ?? total * 100

# Backfill as a job, not a migration
Order::whereNull('total_minor')->chunkById(2000, function ($orders) {
    DB::table('orders')->whereIn('id', $orders->pluck('id'))->update(['total_minor' => DB::raw('ROUND(total * 100)')]);
    usleep(50_000);
});

# Release N+1 (contract): all code reads total_minor; make it required; drop the old column later
Schema::table('orders', fn (Blueprint $t) => $t->unsignedBigInteger('total_minor')->nullable(false)->change());
# Release N+2: $t->dropColumn('total');

# Postgres concurrent index without locking writes
return new class extends Migration {
    public $withinTransaction = false;
    public function up(): void { DB::statement('CREATE INDEX CONCURRENTLY idx_orders_customer_created ON orders (customer_id, created_at)'); }
};

