// Backfill job
Order::whereRaw('BINARY status <> LOWER(status)')->chunkById(2000, fn ($rows) =>
    DB::table('orders')->whereIn('id', $rows->pluck('id'))->update(['status' => DB::raw('LOWER(status)')]));

// Release N+1 (contract 1): verify then constrain
// SELECT status, COUNT(*) FROM orders GROUP BY status;  → only the allowed set remains
Schema::table('orders', fn (Blueprint $t) => $t->string('status', 20)->default('pending')->change());
DB::statement("ALTER TABLE orders ADD CONSTRAINT ck_orders_status CHECK (status IN ('pending','paid','cancelled','refunded'))");

